BEGIN;
SELECT plan(23);
CREATE TEMP TABLE date_results(msg text);
INSERT INTO auth.users(id,aud,role,email,email_confirmed_at) VALUES('a1530000-0000-0000-0000-000000000001','authenticated','authenticated','qa-date-owner@example.test',now());
CREATE TEMP TABLE date_vars(name text,id uuid);
INSERT INTO date_vars SELECT 'ws',id FROM public.workspaces WHERE owner_id='a1530000-0000-0000-0000-000000000001';
UPDATE public.workspaces SET tracking_mode='expense_tracker' WHERE id=(SELECT id FROM date_vars WHERE name='ws');
INSERT INTO date_vars SELECT 'member',id FROM public.workspace_members WHERE workspace_id=(SELECT id FROM date_vars WHERE name='ws');
WITH c AS(INSERT INTO public.credit_cards(workspace_id,name,credit_limit,closing_day,due_day) SELECT id,'Date QA Card',1000,20,10 FROM date_vars WHERE name='ws' RETURNING id) INSERT INTO date_vars SELECT 'card',id FROM c;
WITH p AS(INSERT INTO public.people(workspace_id,name) SELECT id,'Date QA Person' FROM date_vars WHERE name='ws' RETURNING id) INSERT INTO date_vars SELECT 'person',id FROM p;
WITH a AS(INSERT INTO public.accounts(workspace_id,name,type,initial_balance,current_balance) SELECT id,'Date QA Account','checking',1000,1000 FROM date_vars WHERE name='ws' RETURNING id) INSERT INTO date_vars SELECT 'account',id FROM a;
SELECT set_config('request.jwt.claim.sub','a1530000-0000-0000-0000-000000000001',true);
INSERT INTO date_vars SELECT 'pur',public.fn_create_purchase_with_splits(p_workspace_id=>(SELECT id FROM date_vars WHERE name='ws'),p_description=>'Date 600/3',p_total_amount=>600,p_installment_count=>3,p_purchase_date=>'2050-01-10',p_credit_card_id=>(SELECT id FROM date_vars WHERE name='card'),p_account_id=>(SELECT id FROM date_vars WHERE name='account'),p_paid_installments_count=>1,p_paid_by_member_id=>(SELECT id FROM date_vars WHERE name='member'),p_split_type=>'equal',p_splits=>jsonb_build_array(jsonb_build_object('member_id',(SELECT id FROM date_vars WHERE name='member'),'amount',300),jsonb_build_object('person_id',(SELECT id FROM date_vars WHERE name='person'),'amount',300,'repaid_installments_count',1)));
CREATE TEMP TABLE date_original AS SELECT * FROM public.installments WHERE purchase_id=(SELECT id FROM date_vars WHERE name='pur');
CREATE TEMP TABLE date_plan AS SELECT public.fn_purchase_date_schedule((SELECT id FROM date_vars WHERE name='pur'),'2049-12-10') AS schedule,(SELECT repayment_version FROM public.purchases WHERE id=(SELECT id FROM date_vars WHERE name='pur')) AS version;
GRANT ALL ON date_vars,date_plan,date_original,date_results TO authenticated;
SET LOCAL role='authenticated';
INSERT INTO date_results SELECT lives_ok($q$SELECT public.fn_reschedule_purchase_date((SELECT id FROM date_vars WHERE name='ws'),(SELECT id FROM date_vars WHERE name='pur'),'2049-12-10',(SELECT version FROM date_plan),(SELECT schedule FROM date_plan))$q$,'Imported paid installments and repayments can be rescheduled');
INSERT INTO date_results SELECT is((SELECT purchase_date FROM public.purchases WHERE id=(SELECT id FROM date_vars WHERE name='pur')),'2049-12-10'::date,'Purchase date corrected');
INSERT INTO date_results SELECT is((SELECT array_agg(due_date ORDER BY installment_number) FROM public.installments WHERE purchase_id=(SELECT id FROM date_vars WHERE name='pur')),ARRAY['2050-01-10','2050-02-10','2050-03-10']::date[],'All installment due dates recalculated');
INSERT INTO date_results SELECT is((SELECT array_agg(id ORDER BY installment_number) FROM public.installments WHERE purchase_id=(SELECT id FROM date_vars WHERE name='pur')),(SELECT array_agg(id ORDER BY installment_number) FROM date_original),'Installment identities preserved');
INSERT INTO date_results SELECT ok(NOT EXISTS(SELECT 1 FROM public.installments i JOIN date_original old ON old.id=i.id WHERE (i.amount,i.paid_amount,i.paid_at,i.status) IS DISTINCT FROM (old.amount,old.paid_amount,old.paid_at,old.status)),'Amounts, statuses and actual payment dates preserved');
INSERT INTO date_results SELECT is((SELECT repaid_amount FROM public.purchase_splits WHERE purchase_id=(SELECT id FROM date_vars WHERE name='pur') AND person_id IS NOT NULL),100::numeric,'Historical repayment preserved');
INSERT INTO date_results SELECT is((SELECT count(*)::int FROM public.payments WHERE workspace_id=(SELECT id FROM date_vars WHERE name='ws')),0,'Date correction creates no payment');
INSERT INTO date_results SELECT is((SELECT current_balance FROM public.accounts WHERE id=(SELECT id FROM date_vars WHERE name='account')),1000::numeric,'Account balance unchanged');
INSERT INTO date_results SELECT is((SELECT sum(total_amount) FROM public.credit_card_bills WHERE workspace_id=(SELECT id FROM date_vars WHERE name='ws')),600::numeric,'Bill total conserved');
INSERT INTO date_results SELECT is((SELECT sum(paid_amount) FROM public.credit_card_bills WHERE workspace_id=(SELECT id FROM date_vars WHERE name='ws')),200::numeric,'Imported paid amount conserved across bills');
INSERT INTO date_results SELECT throws_ok($q$SELECT public.fn_reschedule_purchase_date((SELECT id FROM date_vars WHERE name='ws'),(SELECT id FROM date_vars WHERE name='pur'),'2049-12-10',(SELECT version FROM date_plan),(SELECT schedule FROM date_plan))$q$,'PT409',NULL,'Stale purchase version rejected');
INSERT INTO date_results SELECT throws_ok($q$SELECT public.fn_reschedule_purchase_date((SELECT id FROM date_vars WHERE name='ws'),(SELECT id FROM date_vars WHERE name='pur'),'2049-12-10',(SELECT repayment_version FROM public.purchases WHERE id=(SELECT id FROM date_vars WHERE name='pur')),'[]')$q$,'PT409',NULL,'Changed preview rejected');
INSERT INTO date_results SELECT throws_ok($q$SELECT public.fn_update_purchase_with_splits(p_workspace_id=>(SELECT id FROM date_vars WHERE name='ws'),p_purchase_id=>(SELECT id FROM date_vars WHERE name='pur'),p_purchase_date=>'2050-03-10',p_credit_card_id=>(SELECT id FROM date_vars WHERE name='card'),p_account_id=>(SELECT id FROM date_vars WHERE name='account'),p_paid_by_member_id=>(SELECT id FROM date_vars WHERE name='member'))$q$,'23514',NULL,'Legacy RPC cannot leave stale installment dates');
SET LOCAL request.jwt.claim.sub='a1530000-0000-0000-0000-000000000002';
INSERT INTO date_results SELECT throws_ok($q$SELECT public.fn_reschedule_purchase_date((SELECT id FROM date_vars WHERE name='ws'),(SELECT id FROM date_vars WHERE name='pur'),'2050-01-01',0,'[]')$q$,'42501',NULL,'Foreign principal denied');
SET LOCAL request.jwt.claim.sub='a1530000-0000-0000-0000-000000000001';
SELECT public.fn_record_payment(p_workspace_id=>(SELECT id FROM date_vars WHERE name='ws'),p_account_id=>NULL,p_amount=>10,p_credit_card_bill_id=>(SELECT credit_card_bill_id FROM public.installments WHERE purchase_id=(SELECT id FROM date_vars WHERE name='pur') AND installment_number=2),p_affects_balance=>false);
RESET ROLE;
TRUNCATE date_plan;
INSERT INTO date_plan SELECT public.fn_purchase_date_schedule((SELECT id FROM date_vars WHERE name='pur'),'2050-02-10'),(SELECT repayment_version FROM public.purchases WHERE id=(SELECT id FROM date_vars WHERE name='pur'));
SET LOCAL role='authenticated';
INSERT INTO date_results SELECT throws_ok($q$SELECT public.fn_reschedule_purchase_date((SELECT id FROM date_vars WHERE name='ws'),(SELECT id FROM date_vars WHERE name='pur'),'2050-02-10',(SELECT version FROM date_plan),(SELECT schedule FROM date_plan))$q$,'23514',NULL,'Recorded bill payment prevents moving its history');
INSERT INTO date_results SELECT is((SELECT purchase_date FROM public.purchases WHERE id=(SELECT id FROM date_vars WHERE name='pur')),'2049-12-10'::date,'Failed correction leaves purchase date unchanged');
INSERT INTO date_results SELECT is((SELECT count(*)::int FROM public.credit_card_bills WHERE workspace_id=(SELECT id FROM date_vars WHERE name='ws')),4,'Failure rolls back newly created target bills');
RESET ROLE;
TRUNCATE date_plan;
INSERT INTO date_plan SELECT public.fn_purchase_date_schedule((SELECT id FROM date_vars WHERE name='pur'),'2049-12-11'),(SELECT repayment_version FROM public.purchases WHERE id=(SELECT id FROM date_vars WHERE name='pur'));
SET LOCAL role='authenticated';
INSERT INTO date_results SELECT lives_ok($q$SELECT public.fn_reschedule_purchase_date((SELECT id FROM date_vars WHERE name='ws'),(SELECT id FROM date_vars WHERE name='pur'),'2049-12-11',(SELECT version FROM date_plan),(SELECT schedule FROM date_plan))$q$,'Date correction inside the same cycles preserves recorded bill payment');
RESET ROLE;
INSERT INTO date_results SELECT ok(NOT has_function_privilege('anon','public.fn_reschedule_purchase_date(uuid,uuid,date,integer,jsonb)','EXECUTE'),'Anonymous execution revoked');
INSERT INTO date_results SELECT ok(NOT has_function_privilege('authenticated','public.fn_purchase_date_schedule(uuid,date)','EXECUTE'),'Internal calendar helper not exposed');
INSERT INTO date_results SELECT is((SELECT count(*)::int FROM public.payments WHERE workspace_id=(SELECT id FROM date_vars WHERE name='ws')),1,'Recorded payment identity preserved');

RESET ROLE;
TRUNCATE date_plan;
INSERT INTO date_plan SELECT public.fn_purchase_date_schedule((SELECT id FROM date_vars WHERE name='pur'),'2050-01-19'),(SELECT repayment_version FROM public.purchases WHERE id=(SELECT id FROM date_vars WHERE name='pur'));
UPDATE public.credit_cards SET closing_day=18 WHERE id=(SELECT id FROM date_vars WHERE name='card');
SET LOCAL role='authenticated';
INSERT INTO date_results SELECT throws_ok($q$SELECT public.fn_reschedule_purchase_date((SELECT id FROM date_vars WHERE name='ws'),(SELECT id FROM date_vars WHERE name='pur'),'2050-01-19',(SELECT version FROM date_plan),(SELECT schedule FROM date_plan))$q$,'PT409',NULL,'Changed card closing settings invalidate the accepted preview');
RESET ROLE;
UPDATE public.credit_cards SET closing_day=20 WHERE id=(SELECT id FROM date_vars WHERE name='card');
TRUNCATE date_plan;
INSERT INTO date_plan SELECT public.fn_purchase_date_schedule((SELECT id FROM date_vars WHERE name='pur'),'2049-12-12'),(SELECT repayment_version FROM public.purchases WHERE id=(SELECT id FROM date_vars WHERE name='pur'));
UPDATE public.credit_card_bills SET due_date=due_date+1 WHERE id=(SELECT (schedule->0->>'target_bill_id')::uuid FROM date_plan);
SET LOCAL role='authenticated';
INSERT INTO date_results SELECT throws_ok($q$SELECT public.fn_reschedule_purchase_date((SELECT id FROM date_vars WHERE name='ws'),(SELECT id FROM date_vars WHERE name='pur'),'2049-12-12',(SELECT version FROM date_plan),(SELECT schedule FROM date_plan))$q$,'PT409',NULL,'Changed existing bill date invalidates the accepted preview');
RESET ROLE;
SELECT (SELECT array_agg(msg) FROM date_results WHERE msg LIKE 'not ok%') AS not_ok_messages,
 extensions._get('curr_test')::int AS ran,extensions._get('plan')::int AS planned,extensions.num_failed()::int AS failed,ARRAY(SELECT * FROM extensions.finish()) AS finish_diagnostics;
ROLLBACK;
